from queueing import payload


def submit(owner, enqueue, batch_size=20):
    if isinstance(batch_size, bool) or not isinstance(batch_size, int):
        raise ValueError("batch_size must be an integer between 1 and 100")
    if not (1 <= batch_size <= 100):
        raise ValueError("batch_size must be an integer between 1 and 100")
    return enqueue(payload(owner, batch_size))

from api import submit
from queueing import payload
from worker import execute


def test_submit_default_batch_size():
    received = []

    def enqueue(p):
        received.append(p)
        return p

    result = submit("alice", enqueue)
    assert result is received[0]
    assert received[0] == {"owner": "alice", "batch_size": 20}


def test_submit_custom_batch_size():
    received = []

    def enqueue(p):
        received.append(p)
        return p

    result = submit("bob", enqueue, 7)
    assert result is received[0]
    assert received[0] == {"owner": "bob", "batch_size": 7}


def test_submit_rejects_bool():
    def enqueue(p):
        raise AssertionError("enqueue must not be called")

    try:
        submit("bob", enqueue, True)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for bool")

    try:
        submit("bob", enqueue, False)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for bool")


def test_submit_rejects_non_integer():
    def enqueue(p):
        raise AssertionError("enqueue must not be called")

    for bad in (1.5, "20", None, [20]):
        try:
            submit("bob", enqueue, bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"expected ValueError for {bad!r}")


def test_submit_rejects_out_of_range():
    def enqueue(p):
        raise AssertionError("enqueue must not be called")

    for bad in (0, -1, 101, 1000):
        try:
            submit("bob", enqueue, bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"expected ValueError for {bad}")


def test_submit_preserves_owner():
    received = []

    def enqueue(p):
        received.append(p)
        return p

    submit("owner-x", enqueue, 33)
    assert received[0]["owner"] == "owner-x"
    assert received[0]["batch_size"] == 33


def test_execute_uses_batch_size():
    calls = []

    def process(owner, batch_size):
        calls.append((owner, batch_size))
        return (owner, batch_size)

    assert execute({"owner": "alice", "batch_size": 5}, process) == ("alice", 5)
    assert execute({"owner": "bob", "batch_size": 99}, process) == ("bob", 99)
    assert calls == [("alice", 5), ("bob", 99)]


def test_execute_legacy_payload_defaults_to_20():
    calls = []

    def process(owner, batch_size):
        calls.append((owner, batch_size))
        return batch_size

    assert execute({"owner": "legacy"}, process) == 20
    assert calls == [("legacy", 20)]


